#!/usr/bin/env python3
"""Optional CDP browser regression checks; needs an existing browser and websockets.

Start the dashboard separately and an installed headless Chromium with
--remote-debugging-port=9331, then pass a new --output directory.
"""
import argparse
import asyncio
import base64
import json
from pathlib import Path
from urllib.request import urlopen
import websockets

parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--url',default='http://127.0.0.1:8786')
parser.add_argument('--devtools-url',default='http://127.0.0.1:9331')
parser.add_argument('--output',type=Path,required=True)
args=parser.parse_args()
URL=args.url.rstrip('/')
OUT=args.output
OUT.mkdir(parents=True,exist_ok=False)

async def main():
    tabs=json.load(urlopen(args.devtools_url.rstrip('/')+'/json/list'))
    tab=next(t for t in tabs if t['type']=='page')
    async with websockets.connect(tab['webSocketDebuggerUrl'],max_size=20_000_000) as ws:
        seq=0;errors=[];checks=[]
        async def rpc(method,params=None):
            nonlocal seq
            seq+=1;current=seq
            await ws.send(json.dumps({'id':current,'method':method,'params':params or {}}))
            while True:
                message=json.loads(await ws.recv())
                if message.get('method')=='Runtime.exceptionThrown':errors.append(message['params'])
                if message.get('id')==current:
                    if 'error' in message:raise RuntimeError(message['error'])
                    return message.get('result',{})
        async def evaluate(js):
            result=await rpc('Runtime.evaluate',{'expression':js,'returnByValue':True,'awaitPromise':True})
            if 'exceptionDetails' in result:raise RuntimeError(result['exceptionDetails'])
            return result['result'].get('value')
        async def wait(js):
            for _ in range(900):
                if await evaluate(js):return
                await asyncio.sleep(.2)
            raise AssertionError('Timeout: '+js)
        async def check(label,js):
            assert await evaluate(js),label
            checks.append(label)
        await rpc('Runtime.enable')
        await rpc('Page.enable')
        await rpc('Emulation.setDeviceMetricsOverride',{'width':1440,'height':1100,'deviceScaleFactor':1,'mobile':False})
        await rpc('Page.navigate',{'url':URL})
        await wait("typeof data !== 'undefined' && !!data && !!document.querySelector('[data-engine-track]')")
        await check('engine overview is the default and counts each track',"state.view==='engine' && document.querySelector('nav [data-view=engine]').getAttribute('aria-current')==='page' && document.querySelectorAll('[data-engine-track]').length===data.tracks.filter(t=>!t.planned).length && document.querySelector('#kind').closest('.scope-control').hidden")
        await check('engine stage counts follow the register',"data.tracks.filter(t=>!t.planned).every(t=>{const row=document.querySelector('[data-engine-track='+t.id+']');const s=summarize(t.behaviors.map(id=>behaviorById.get(id)));return row.cells[1].textContent.includes(s.scoped+' / '+s.total+' implemented') && (!s.recovered || row.cells[2].textContent.includes(s.current+' / '+s.recovered+' current'));})")
        await check('engine overview totals deduplicate shared contracts',"document.querySelector('.track-summary').children[0].querySelector('strong').textContent===(()=>{const ids=new Set(data.tracks.filter(t=>!t.planned).flatMap(t=>t.behaviors));const s=summarize(data.behaviors.filter(b=>ids.has(b.id)));return s.scoped+' / '+s.total;})()")
        await check('engine navigation and shared status definitions use implementation language', "document.querySelector('nav [data-view=engine]').textContent.trim().endsWith('Engine overview') && ['Implemented','Partially implemented','Not implemented'].every(label=>document.querySelector('.status-guide').textContent.includes(label))")
        await check('milestone implementation stays independent from evidence requirements', "(()=>{const original=behaviorById;try{behaviorById=new Map([['a',{status:{implementation:'scoped'}}],['b',{status:{implementation:'none'}}],['p',{status:{implementation:'partial'}}]]);const m={behaviors:['a'],missing:[],state:'in_progress',current:false};return milestoneImplementation(m)==='scoped' && milestoneStatus(m).includes('>Implemented<') && milestoneStatus(m).includes('Milestone requirements pending') && milestoneImplementation({...m,behaviors:['a','b']})==='partial' && milestoneImplementation({...m,behaviors:['p']})==='partial' && milestoneImplementation({...m,behaviors:['b']})==='none' && milestoneImplementation({...m,missing:['absent']})==='unknown' && milestoneImplementation({...m,behaviors:[]})==='unknown';}finally{behaviorById=original;}})()")
        engine=await rpc('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False})
        (OUT/'engine-desktop.png').write_bytes(base64.b64decode(engine['data']))
        await evaluate("document.querySelector('#view-content [data-view=simulation]').click()")
        await check('simulation roadmap follows milestone states',"state.view==='simulation' && data.tracks.find(t=>t.id==='simulation').milestones.every(m=>document.querySelector('[data-simulation-milestone='+m.id+'] .milestone-status .badge:last-child').textContent===milestoneLabels[m.state])")
        await check('focus roadmap shows implementation independently for every milestone', "data.tracks.find(t=>t.id==='simulation').milestones.every(m=>{const values=m.behaviors.map(id=>behaviorById.get(id).status.implementation);const expected=m.missing.length||!values.length?'Implementation unknown':values.every(v=>v==='scoped')?'Implemented':values.some(v=>v!=='none')?'Registered partial':'Not implemented';return document.querySelector('[data-simulation-milestone='+m.id+'] [data-stage=implementation]').textContent===expected;})")
        await check('simulation ownership boundaries stay visible',"document.querySelector('.render-boundary').textContent.includes('Complete original world scheduling') && document.querySelector('[data-simulation-milestone=live-simulation]').textContent.includes('Not implemented')")
        await evaluate("document.querySelector('[data-track-work=simulation]').click()")
        await check('simulation drilldown includes both native policies and recovered AI',"state.view==='work' && state.track==='simulation' && state.kind==='all' && scopedBehaviors().some(b=>b.id==='NP.native-owner-skirmish') && scopedBehaviors().some(b=>b.id==='AI.owner-multisource-pipeline-trace')")
        await rpc('Page.navigate',{'url':URL+'/#view=simulation'})
        await wait("typeof data !== 'undefined' && !!data && !!document.querySelector('[data-simulation-milestone]')")
        await check('simulation bookmark restores focus',"state.view==='simulation'")
        simulation=await rpc('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False})
        (OUT/'simulation-desktop.png').write_bytes(base64.b64decode(simulation['data']))
        await evaluate("document.querySelector('[data-view=rendering]').click()")
        await wait("typeof data !== 'undefined' && !!data && !!document.querySelector('[data-render-milestone]')")
        await check('native rendering remains a permanent view',"state.view==='rendering' && document.querySelector('nav [data-view=rendering]').getAttribute('aria-current')==='page' && document.querySelectorAll('[data-render-milestone]').length===data.tracks.find(t=>t.id==='rendering').milestones.length && document.querySelector('#kind').closest('.scope-control').hidden")
        await check('native focus retains current registered boundaries and separate next tasks',"document.querySelector('.render-boundary').textContent.includes(data.tracks.find(t=>t.id==='rendering').focus.boundary) && document.querySelector('[data-progress-section=implementation]').textContent.includes(data.tracks.find(t=>t.id==='rendering').focus.implementation_title) && document.querySelector('[data-progress-section=validation]').textContent.includes(data.tracks.find(t=>t.id==='rendering').focus.next_title) && document.querySelector('[data-render-milestone=word-takeover]').textContent.includes('fully in-bounds')")
        await check('rendering sections have separate denominators and complete implementation gaps', "(()=>{const t=data.tracks.find(t=>t.id==='rendering'),rows=t.behaviors.map(id=>behaviorById.get(id)),i=document.querySelector('[data-progress-section=implementation]'),v=document.querySelector('[data-progress-section=validation]');return i.textContent.includes(rows.length+' registered behaviors') && i.querySelectorAll('.implementation-gap-list [data-behavior]').length===rows.filter(b=>b.status.implementation!=='scoped').length && v.textContent.includes(t.milestones.length+' curated milestones') && !i.querySelector('[data-stage=integration]') && !v.querySelector('[data-stage=implementation]');})()")
        await check('rendering milestone implementation and validation are independent', "data.tracks.find(t=>t.id==='rendering').milestones.every(m=>{const card=document.querySelector('[data-render-milestone='+m.id+']');const expected=m.missing.length||!m.checks.length?'unknown':m.checks.every(c=>c.validation_current)?'current':m.checks.every(c=>c.validation_met)?'historical':'pending';return card.querySelector('.milestone-implementation [data-stage=implementation]').textContent===statusLabel('implementation',milestoneImplementation(m)) && card.querySelector('.milestone-validation').dataset.validationState===expected;})")
