        await check('every tranche task has actionable implementation validation and exit details', "[...document.querySelectorAll('[data-tranche-behavior]')].every(e=>e.textContent.includes('Next action:')&&e.textContent.includes('Implementation boundary:')&&e.textContent.includes('Validation:')&&e.textContent.includes('Completion condition:')&&e.querySelector('a'))")
        await check('tranche three labels code independently from retained acceptance failures', "(()=>{const t=document.querySelector('[data-critical-tranche=session-acceptance]');return t.querySelectorAll('[data-work-implementation=implemented_within_scope]').length===10&&t.querySelectorAll('[data-work-implementation=unresolved_aggregate]').length===1&&t.querySelectorAll('[data-work-acceptance=acceptance_failure]').length===2&&t.querySelectorAll('[data-work-review]').length===11&&t.querySelector('[data-tranche-work-summary]').textContent.includes('0 Partially implemented');})()")
        await check('tranche three state and next steps do not promote registered stages', "data.importance.tranche_plan.tranches[2].tasks.every(task=>{const row=document.querySelector('[data-tranche-behavior=\"'+task.behavior+'\"]');return row.textContent.includes(task.work_review.current_state)&&task.work_review.next_steps.every(step=>row.textContent.includes(step.action))&&row.textContent.includes('Registered execution-accounting status: Registered partial')&&behaviorById.get(task.behavior).status.implementation==='partial';})")
        await check('tranche two retains implementation boundaries after eleven bounded passes', "(()=>{const t=document.querySelector('[data-critical-tranche=canvas-producers]');return t.querySelectorAll('[data-work-implementation=implemented_within_scope]').length===8&&t.querySelectorAll('[data-work-implementation=unresolved_aggregate]').length===3&&t.querySelectorAll('[data-work-acceptance=acceptance_failure]').length===0&&t.querySelectorAll('[data-work-review]').length===11&&t.querySelectorAll('[data-task-result=PASS]').length===11&&t.querySelector('[data-tranche-work-summary]').textContent.includes('0 Partially implemented');})()")
        await check('tranche two shows current state typed next steps and supplied controls without promotions', "data.importance.tranche_plan.tranches[1].tasks.every(task=>{const row=document.querySelector('[data-tranche-behavior=\"'+task.behavior+'\"]');return row.textContent.includes(task.work_review.current_state)&&task.work_review.next_steps.every(step=>row.textContent.includes(step.action))&&row.textContent.includes('Supplied controls')&&row.textContent.includes('Registered execution-accounting status: Registered partial')&&behaviorById.get(task.behavior).status.implementation==='partial';})")
        await check('tranche one preserves earlier failures after bounded acceptance', "(()=>{const t=document.querySelector('[data-critical-tranche=storage-ownership]');return t.querySelectorAll('[data-work-implementation=implemented_within_scope]').length===11&&t.querySelectorAll('[data-work-implementation=unresolved_aggregate]').length===0&&t.querySelectorAll('[data-work-acceptance=acceptance_failure]').length===0&&t.querySelectorAll('[data-task-result=PASS]').length===11&&!!t.querySelector('[data-history-result=FAIL]');})()")
        await check('partial advice follows source assessment instead of assuming missing branches', "(()=>{const b=behaviorById.get('NP.surface-final-word-read'),a=behaviorById.get('NR.surfaces');return implementationBadge(b).includes('Implemented within scope')&&implementationGapAdvice(b).includes('No concrete missing code')&&implementationGapAdvice(a).includes('Unresolved aggregate')&&implementationBadge({status:{implementation:'partial'}}).includes('Scope review pending')&&document.querySelector('.status-guide').textContent.includes('a concrete required branch, mechanism or supported domain is missing');})()")
        await check('source assessment filters separate missing code aggregates and acceptance', "(()=>{const old=importanceStatus;try{const track=data.tracks.find(t=>t.id==='rendering');return ['partially_implemented','implemented_within_scope','unresolved_aggregate','not_implemented','acceptance_failure'].every(key=>{importanceStatus=key;const html=importanceView(track),expected=track.behaviors.map(id=>behaviorById.get(id)).filter(b=>key==='acceptance_failure'?b.tranche_task?.work_review?.acceptance===key:b.tranche_task?.work_review?.implementation===key).length;return (html.match(/data-importance-behavior=/g)||[]).length===expected;});}finally{importanceStatus=old;}})()")
        await check('High plan covers all 51 unfinished High contracts once in three groups', "(()=>{const p=data.importance.high_tranche_plan,tasks=p.tranches.flatMap(t=>t.tasks),expected=data.importance.entries.filter(e=>e.weight===4&&e.implementation!=='scoped').map(e=>e.behavior);return p.state==='planned'&&p.unplanned_high.length===0&&p.selected_count===51&&p.tranches.length===3&&p.tranches.every(t=>t.tasks.length===17)&&new Set(tasks.map(t=>t.behavior)).size===51&&expected.length===51&&expected.every(id=>tasks.some(t=>t.behavior===id))&&tasks.every(t=>!t.execution_result&&behaviorById.get(t.behavior).tranche_task.plan_priority==='High');})()")
        await check('High assessments distinguish validation aggregates and missing model', "(()=>{const p=document.querySelector('[data-high-plan]');return document.querySelectorAll('[data-high-tranche]').length===3&&p.querySelectorAll('[data-high-tranche-behavior]').length===51&&p.querySelectorAll('[data-work-implementation=implemented_within_scope]').length===48&&p.querySelectorAll('[data-work-implementation=unresolved_aggregate]').length===2&&p.querySelectorAll('[data-work-implementation=not_implemented]').length===1&&[...p.querySelectorAll('[data-high-tranche-behavior]')].every(e=>e.textContent.includes('Next action:')&&e.textContent.includes('Validation state:')&&e.textContent.includes('Completion condition:'));})()")
        await evaluate("openBehavior('RS.displacement-final-word-read')")
        await check('missing original model retains native padding boundary and registered none', "document.querySelector('#detail-body').textContent.includes('High')&&document.querySelector('#detail-body').textContent.includes('padding')&&document.querySelector('#detail-body [data-stage=implementation]').textContent==='Not implemented'&&document.querySelector('#detail-body').textContent.includes('Recover the exact live operand')")
        await evaluate("document.querySelector('#close-detail').click();document.querySelector('[data-high-plan]').closest('section').scrollIntoView()")
        high_desktop=await rpc('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False})
        (OUT/'high-tranches-desktop.png').write_bytes(base64.b64decode(high_desktop['data']))
        await evaluate("document.querySelector('[data-critical-plan]').closest('section').scrollIntoView()")
        tranches_desktop=await rpc('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False})
        (OUT/'tranches-desktop.png').write_bytes(base64.b64decode(tranches_desktop['data']))
        await evaluate("openBehavior('NP.surface-final-word-read')")
        await check('behavior detail includes the planned tranche and bounded next action', "document.querySelector('#detail-body').textContent.includes('Planned Critical tranche 1')&&!!document.querySelector('#detail-body [data-execution-brief]') && document.querySelector('#detail-body code').textContent.includes('tools/test-native-draw-surfaces.py')&&document.querySelector('#detail-body').textContent.includes('Completion condition:')&&document.querySelector('#detail-body [data-stage=implementation]').textContent==='Registered partial'")
